@Component
@StepScope
@RequiredArgsConstructor
class CatalogoClavesAfc {
    private final CatalogoClient l710;          // L710_CONSUL_DETALLE IN ESTRUCTURA (S080BD01CON)

    /** WKS-CVE-SIS: clave de transacción a AFC (1 abono, 2 cargo). Se carga por sistema. */
    Map<Integer, Integer> carga(int sistema, int formatoCatalogo, int numCatalogo) {
        Map<Integer, Integer> afcPorClave = new HashMap<>();      // se crea vacío en cada sistema
        for (RenglonL710 r : l710.consultaDetalle(151, 30, numCatalogo, sistema, formatoCatalogo)) {
            int indice = (formatoCatalogo == 2) ? r.dato(2) : r.dato(1);   // 0530-MUEVE-CLAVE
            if (indice >= 9999) {
                log.info("CVE.TRANSACCION > 9999 ");            // el fuente lo informa y lo omite
                continue;
            }
            afcPorClave.put(indice, r.dato(15));                 // WKS-CVE-AFC(W77-IND)
        }
        return Map.copyOf(afcPorClave);
    }
}

